import datetime
start = datetime.date(2026,10,5)
print('start weekday', start.strftime('%A'))
holiday = datetime.date(2026,10,12)

def is_business_day(d):
    return d.weekday() < 5 and d != holiday

def add_business_days(start_date, n, start_counts=True):
    # returns the date that is the nth business day counting start_date as day1 if it's a business day
    d = start_date
    count = 0
    while True:
        if is_business_day(d):
            count += 1
            if count == n:
                return d
        d += datetime.timedelta(days=1)

def next_business_day(d):
    d = d + datetime.timedelta(days=1)
    while not is_business_day(d):
        d += datetime.timedelta(days=1)
    return d

phases = [('Discovery',3), ('Build',6), ('QA',4), ('Release',1)]
cur_start = start
for name, dur in phases:
    end = add_business_days(cur_start, dur)
    print(name, 'start', cur_start, 'end', end)
    cur_start = next_business_day(end)
print('Launch date (end of Release) =', end)
